import{_ as l,C as d,o,c as u,a2 as i,b as n,w as a,a as r,E as s,a3 as c}from"./chunks/framework.CgxQ0r6v.js";const v=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_1.md"}'),m={name:"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_1.md"};function p(I,e,f,A,g,C){const t=d("Mermaid");return o(),u("div",null,[e[2]||(e[2]=i('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-vii" tabindex="-1">Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VII) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-vii" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VII)&quot;">​</a></h2><h3 id="eje-tematico-diagnostico-participativo-cuantitativo-y-abordaje-institucional" tabindex="-1">Eje Temático: Diagnóstico Participativo Cuantitativo y Abordaje Institucional <a class="header-anchor" href="#eje-tematico-diagnostico-participativo-cuantitativo-y-abordaje-institucional" aria-label="Permalink to &quot;Eje Temático: Diagnóstico Participativo Cuantitativo y Abordaje Institucional&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-madurez-sociotecnologica-en-el-trayecto-iii" tabindex="-1">🧭 Introducción: La Madurez Sociotecnológica en el Trayecto III <a class="header-anchor" href="#🧭-introduccion-la-madurez-sociotecnologica-en-el-trayecto-iii" aria-label="Permalink to &quot;🧭 Introducción: La Madurez Sociotecnológica en el Trayecto III&quot;">​</a></h2><p>El <strong>Trayecto III</strong> marca el ingreso de los estudiantes a la etapa de profesionalización de la Licenciatura / Ingeniería en Informática. En los trayectos previos se dominaron el soporte técnico (PST I) y el desarrollo de aplicaciones para unidades comunitarias pequeñas (PST II).</p><p>En el <strong>Proyecto Sociotecnológico III (PST III)</strong>, el alcance se amplía significativamente:</p><ul><li><strong>Organizaciones de Mayor Complejidad:</strong> Instituciones de salud de segundo nivel, distritos escolares, empresas de propiedad social indirecta, redes comunitarias interconectadas o dependencias de la administración pública regional.</li><li><strong>Volumen y Cuantificación de Datos:</strong> Ya no basta con decir &quot;se pierde la información&quot;. En PST III es obligatorio cuantificar: cuántos registros diarios se procesan, cuántos usuarios concurrentes interactúan, cuál es la tasa de crecimiento mensual de los datos y cuál es el costo operativo del retraso actual.</li><li><strong>Enfoque de Arquitectura Empresarial:</strong> Los requerimientos trascienden la simple pantalla CRUD para integrar seguridad por roles jerárquicos, auditoría de transacciones y necesidades de comunicación en red.</li></ul>',8)),(o(),n(c,null,{default:a(()=>[s(t,{id:"mermaid-36",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%22%F0%9F%91%A5%20PST%20I%3A%20Soporte%20Comunitario%22%5D%20--%3E%20B%5B%22%F0%9F%92%BB%20PST%20II%3A%20Aplicaciones%20B%C3%A1sicas%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%8F%A2%20PST%20III%3A%20Sistemas%20de%20Informaci%C3%B3n%20Institucionales%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%8C%90%20PST%20IV%3A%20Soluciones%20Integrales%20de%20Ingenier%C3%ADa%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20B%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20C%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20D%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<hr><h2 id="🏛️-capitulo-i-abordaje-a-instituciones-de-mediana-y-gran-escala" tabindex="-1">🏛️ CAPÍTULO I: Abordaje a Instituciones de Mediana y Gran Escala <a class="header-anchor" href="#🏛️-capitulo-i-abordaje-a-instituciones-de-mediana-y-gran-escala" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Abordaje a Instituciones de Mediana y Gran Escala&quot;">​</a></h2><p>El abordaje en PST III suele realizarse en organizaciones que cuentan con departamentos, jerarquías formales y normativas internas estrictas.</p><h3 id="_1-1-mapeo-de-actores-y-niveles-de-decision" tabindex="-1">1.1 Mapeo de Actores y Niveles de Decisión <a class="header-anchor" href="#_1-1-mapeo-de-actores-y-niveles-de-decision" aria-label="Permalink to &quot;1.1 Mapeo de Actores y Niveles de Decisión&quot;">​</a></h3><p>En una organización institucional, los actores se clasifican en tres niveles:</p><ol><li><strong>Nivel Estratégico (Directiva / Coordinadores Generales):</strong> Les interesa la visión global, la seguridad institucional, los reportes consolidados y el cumplimiento normativo.</li><li><strong>Nivel Táctico (Jefes de Departamento / Supervisores):</strong> Administran los flujos de trabajo, aprueban transacciones y supervisan al personal operativo.</li><li><strong>Nivel Operativo (Secretarias, Técnicos, Operadores de Ventanilla):</strong> Quienes alimentan el sistema diariamente y padecen directamente los cuellos de botella del papeleo.</li></ol><hr><h2 id="📊-capitulo-ii-levantamiento-cuantitativo-de-informacion" tabindex="-1">📊 CAPÍTULO II: Levantamiento Cuantitativo de Información <a class="header-anchor" href="#📊-capitulo-ii-levantamiento-cuantitativo-de-informacion" aria-label="Permalink to &quot;📊 CAPÍTULO II: Levantamiento Cuantitativo de Información&quot;">​</a></h2><p>A diferencia de diagnósticos puramente narrativos, en el PST III la recolección de datos debe incluir <strong>técnicas de cuantificación de procesos</strong>:</p>',9)),(o(),n(c,null,{default:a(()=>[s(t,{id:"mermaid-74",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20M%5B%22%F0%9F%93%8A%20M%C3%A9tricas%20Cuantitativas%20del%20Diagn%C3%B3stico%22%5D%0A%20%20%20%20M%20--%3E%20V%5B%22%F0%9F%93%A6%20Volumen%20de%20Datos%3A%20N%C2%B0%20de%20expedientes%20f%C3%ADsicos%20y%20tama%C3%B1o%20proyectado%22%5D%0A%20%20%20%20M%20--%3E%20T%5B%22%E2%8F%B1%EF%B8%8F%20Tiempo%20de%20Ciclo%3A%20Horas%2Fd%C3%ADas%20requeridos%20para%20tramitar%20una%20solicitud%22%5D%0A%20%20%20%20M%20--%3E%20F%5B%22%F0%9F%93%88%20Frecuencia%20Transaccional%3A%20Operaciones%20por%20d%C3%ADa%2Fhora%20pico%22%5D%0A%20%20%20%20M%20--%3E%20E%5B%22%E2%9D%8C%20Tasa%20de%20Error%3A%20Porcentaje%20de%20documentos%20extraviados%20o%20con%20datos%20err%C3%B3neos%22%5D%0A%0A%20%20%20%20style%20M%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20V%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20T%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20F%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20E%20fill%3A%23b45309%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<h3 id="_2-1-ejemplo-de-analisis-cuantitativo-en-el-informe" tabindex="-1">2.1 Ejemplo de Análisis Cuantitativo en el Informe <a class="header-anchor" href="#_2-1-ejemplo-de-analisis-cuantitativo-en-el-informe" aria-label="Permalink to &quot;2.1 Ejemplo de Análisis Cuantitativo en el Informe&quot;">​</a></h3><blockquote><p><em>&quot;En el departamento de Control de Estudios del Instituto Tecnológico &#39;X&#39;, se procesan actualmente un promedio de 450 solicitudes de constancias mensuales de forma 100% manual. Cada trámite demora en promedio 4.5 días hábiles debido a la búsqueda física en archivadores. Se estima una tasa de pérdida o deterioro de expedientes del 3.2% anual, afectando a más de 120 estudiantes por período.&quot;</em></p></blockquote><hr><h2 id="📋-capitulo-iii-especificacion-de-requerimientos-avanzados-ieee-830" tabindex="-1">📋 CAPÍTULO III: Especificación de Requerimientos Avanzados (IEEE 830) <a class="header-anchor" href="#📋-capitulo-iii-especificacion-de-requerimientos-avanzados-ieee-830" aria-label="Permalink to &quot;📋 CAPÍTULO III: Especificación de Requerimientos Avanzados (IEEE 830)&quot;">​</a></h2><p>En PST III, los requerimientos no funcionales (RNF) adquieren un peso determinante en la arquitectura:</p><table tabindex="0"><thead><tr><th>Requerimiento No Funcional</th><th>Dimensión Técnica</th><th>Criterio de Éxito / Métrica</th></tr></thead><tbody><tr><td><strong>Concurrencia</strong></td><td>El sistema debe soportar un mínimo de 30 usuarios simultáneos en red local sin degradación perceptible.</td><td>Tiempo de respuesta &lt; 1.5 seg en carga máxima.</td></tr><tr><td><strong>Auditoría y Trazabilidad</strong></td><td>Toda operación de creación, modificación o anulación debe registrar automáticamente: usuario, fecha, hora, IP y estado previo.</td><td>Tabla de auditoría inmutable (<code>logs_auditoria</code>).</td></tr><tr><td><strong>Respaldo Automático</strong></td><td>El sistema debe ejecutar volcados automáticos diarios de la base de datos a un dispositivo de almacenamiento secundario.</td><td>Copia programada diaria a las 23:00 hrs.</td></tr><tr><td><strong>Interoperabilidad</strong></td><td>El sistema debe ser capaz de exportar e importar datos en formatos abiertos universales (CSV, JSON, PDF).</td><td>Cumplimiento del estándar W3C y Ley de Infogobierno.</td></tr></tbody></table><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-1" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 1 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-1" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 1&quot;">​</a></h2><p>Para la Evaluación 1 del Trimestre VII:</p><ol><li><strong>Carta de Aceptación Institucional:</strong> Sellada y firmada por la máxima autoridad del organismo.</li><li><strong>Informe de Diagnóstico Cuantitativo:</strong> Con gráficas y tablas de volumetría de datos y tiempos de ciclo actuales.</li><li><strong>Catálogo de Requerimientos ERS Completo:</strong> Con especificación formal de Requisitos Funcionales y No Funcionales avanzados.</li></ol>',10))])}const h=l(m,[["render",p]]);export{v as __pageData,h as default};
